import request from 'supertest';
import { describe, expect, it } from 'vitest';
import { createApp } from '../src/app.ts';

describe('users api', () => {
  it('creates, gets, lists, updates, deletes, and enforces problems/idempotency', async () => {
    const app = createApp();

    const created = await request(app)
      .post('/v1/users')
      .send({ email: 'alice@example.com', name: 'Alice' })
      .expect(201);

    expect(created.headers.location).toBe(`/v1/users/${created.body.id}`);
    expect(created.headers['content-type']).toContain('application/json');
    expect(created.body.email).toBe('alice@example.com');
    expect(created.body.role).toBe('member');

    await request(app)
      .post('/v1/users')
      .send({ email: 'alice@example.com', name: 'Other' })
      .expect(409)
      .expect('content-type', /application\/problem\+json/);

    const got = await request(app).get(`/v1/users/${created.body.id}`).expect(200);
    expect(got.body).toEqual(created.body);

    const listed = await request(app).get('/v1/users?limit=20').expect(200);
    expect(listed.body.data).toHaveLength(1);
    expect(listed.body.nextCursor).toBeNull();

    const patched = await request(app)
      .patch(`/v1/users/${created.body.id}`)
      .send({ name: 'Alice Updated', role: 'admin' })
      .expect(200);
    expect(patched.body.name).toBe('Alice Updated');
    expect(patched.body.role).toBe('admin');

    await request(app).delete(`/v1/users/${created.body.id}`).expect(204);
    await request(app).get(`/v1/users/${created.body.id}`).expect(404);
  });
});

