import type { Router, Request, Response } from 'express';
import { z } from 'zod';
import { conflict, notFound, unprocessable } from '../lib/problem.ts';
import { paginate, pageSchema } from '../lib/pagination.ts';
import { idempotency, IdempotencyHeadersSchema } from '../lib/idempotency.ts';

const UserIdSchema = z.string().uuid();
const UserRoleSchema = z.enum(['admin', 'member']);
const UserSchema = z.object({
  id: z.string().uuid(),
  email: z.string().email(),
  name: z.string().min(1).max(100),
  role: UserRoleSchema,
  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
});
const UsersListResponseSchema = pageSchema(UserSchema);
const CreateUserBodySchema = z.object({
  email: z.string().email(),
  name: z.string().min(1).max(100),
  role: UserRoleSchema.optional(),
});
const UpdateUserBodySchema = z.object({
  email: z.string().email().optional(),
  name: z.string().min(1).max(100).optional(),
  role: UserRoleSchema.optional(),
}).refine((value) => Object.keys(value).length > 0, { message: 'at least one field is required' });
const CursorQuerySchema = z.object({ limit: z.coerce.number().int().positive().max(100).default(20), cursor: z.string().optional() });

type User = z.infer<typeof UserSchema>;
type CreateUserBody = z.infer<typeof CreateUserBodySchema>;
type UpdateUserBody = z.infer<typeof UpdateUserBodySchema>;

type Store = { users: User[]; idempotency: Map<string, unknown> };

function nowIso(): string { return new Date().toISOString(); }
function createStore(): Store { return { users: [], idempotency: new Map() }; }
