import request from 'supertest';
import { describe, expect, it } from 'vitest';
import { createApp } from '../src/app.ts';

describe('users api', () => {
  it('supports full user lifecycle and validation', async () => {
    const app = createApp();

    const created = await request(app)
      .post('/v1/users')
      .send({ email: 'a@example.com', name: 'Alice' })
      .expect(201);

    expect(created.headers.location).toBe(`/v1/users/${created.body.id}`);
    expect(created.body.role).toBe('member');

    const list = await request(app).get('/v1/users').expect(200);
    expect(list.body.data).toHaveLength(1);

    await request(app)
      .patch(`/v1/users/${created.body.id}`)
      .send({ name: 'Alicia' })
      .expect(200);

    await request(app).delete(`/v1/users/${created.body.id}`).expect(204);
    await request(app).get(`/v1/users/${created.body.id}`).expect(404);
  });
});

import type { Router } from 'express';
import { z } from 'zod';
import { conflict, notFound, unprocessable } from '../lib/problem.ts';
import { CursorQuerySchema, paginate, pageSchema } from '../lib/pagination.ts';
import { idempotency, IdempotencyHeadersSchema } from '../lib/idempotency.ts';

const UserIdSchema = z.string().uuid();
const UserRoleSchema = z.enum(['admin', 'member']);
const UserSchema = z.object({
  id: z.string().uuid(),
  email: z.string().email(),
  name: z.string().min(1).max(100),
  role: UserRoleSchema,
  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
});
const UsersListResponseSchema = pageSchema(UserSchema);
const CreateUserBodySchema = z.object({ email: z.string().email(), name: z.string().min(1).max(100), role: UserRoleSchema.optional() });
const UpdateUserBodySchema = z.object({ email: z.string().email().optional(), name: z.string().min(1).max(100).optional(), role: UserRoleSchema.optional() });
const UserParamsSchema = z.object({ userId: UserIdSchema });
const CursorQueryForUsersSchema = CursorQuerySchema;
const ProblemBodySchema = z.object({ detail: z.string() });

const StoreSchema = z.object({ users: z.array(UserSchema), idempotency: z.instanceof(Map<string, unknown>) });
type Store = z.infer<typeof StoreSchema>;

function nowIso(): string { return new Date().toISOString(); }
function createStore(): Store { return { users: [], idempotency: new Map() }; }
function createUser(input: z.infer<typeof CreateUserBodySchema>): z.infer<typeof UserSchema> { const now = nowIso(); return { id: crypto.randomUUID(), email: input.email, name: input.name, role: input.role ?? 'member', createdAt: now, updatedAt: now }; }
function findUser(store: Store, id: string): z.infer<typeof UserSchema> | undefined { return store.users.find((u) => u.id === id); }
function ensureUniqueEmail(store: Store, email: string, excludeId?: string): void { if (store.users.some((u) => u.email === email && u.id !== excludeId)) throw conflict('A user with that email already exists.'); }
function validateRequest<T>(schema: z.ZodType<T>, value: unknown, detailPrefix: string): T { const parsed = schema.safeParse(value); if (!parsed.success) throw unprocessable(`${detailPrefix}: ${parsed.error.issues.map((i) => i.path.join('.') || 'value').join(', ')}`); return parsed.data; }

function buildUsersRouter(store: Store): Router {
  const router: Router = (require('express').Router()) as Router;
  router.use(idempotency());
  router.get('/v1/users', (req, res, next) => {
    try { const query = CursorQueryForUsersSchema.parse(req.query); return res.json(UsersListResponseSchema.parse(paginate(store.users, query, (u) => u.id))); } catch (err) { return next(err); }
  });
  router.post('/v1/users', (req, res, next) => {
    try { IdempotencyHeadersSchema.parse(req.headers); const body = CreateUserBodySchema.parse(req.body); ensureUniqueEmail(store, body.email); const user = createUser(body); store.users.push(user); return res.status(201).location(`/v1/users/${user.id}`).json(UserSchema.parse(user)); } catch (err) { return next(err); }
  });
  router.get('/v1/users/:userId', (req, res, next) => {
    try { const { userId } = UserParamsSchema.parse(req.params); const user = findUser(store, userId); if (!user) throw notFound('User not found.'); return res.json(UserSchema.parse(user)); } catch (err) { return next(err); }
  });
  router.patch('/v1/users/:userId', (req, res, next) => {
    try { const { userId } = UserParamsSchema.parse(req.params); const body = UpdateUserBodySchema.parse(req.body); if (Object.keys(body).length === 0) throw unprocessable('At least one field must be provided.'); const user = findUser(store, userId); if (!user) throw notFound('User not found.'); if (body.email !== undefined) ensureUniqueEmail(store, body.email, user.id); Object.assign(user, body, { updatedAt: nowIso() }); return res.json(UserSchema.parse(user)); } catch (err) { return next(err); }
  });
  router.delete('/v1/users/:userId', (req, res, next) => {
    try { const { userId } = UserParamsSchema.parse(req.params); const index = store.users.findIndex((u) => u.id === userId); if (index < 0) throw notFound('User not found.'); store.users.splice(index, 1); return res.status(204).send(); } catch (err) { return next(err); }
  });
  return router;
}

export function registerRoutes(app: Router): void { app.use(buildUsersRouter(createStore())); }

