function createStore(): Store { return { users: [] }; }
function createUser(input: CreateUserBody): User { const now = nowIso(); return { id: crypto.randomUUID(), email: input.email, name: input.name, role: input.role ?? 'member', createdAt: now, updatedAt: now }; }
function findUser(store: Store, id: string): User | undefined { return store.users.find((u) => u.id === id); }
function ensureUniqueEmail(store: Store, email: string, excludeId?: string): void { if (store.users.some((u) => u.email === email && u.id !== excludeId)) throw conflict('A user with that email already exists.'); }
function validateRequest<T>(schema: z.ZodType<T>, value: unknown, detailPrefix: string): T { const parsed = schema.safeParse(value); if (!parsed.success) throw unprocessable(`${detailPrefix}: ${parsed.error.issues.map((i) => i.path.join('.') || 'body').join(', ')}`); return parsed.data; }

