  const router: Router = express.Router();
  router.get('/v1/users', (req: Request, res: Response) => { const query = validateRequest(SharedCursorQuerySchema, req.query, 'Invalid query'); const page = paginate(store.users, query, (user) => user.id); res.json(UsersListResponseSchema.parse(page)); });
  router.post('/v1/users', idempotency(), (req: Request, res: Response) => { const body = validateRequest(CreateUserBodySchema, req.body, 'Invalid body'); ensureUniqueEmail(store, body.email); const user = createUser(body); store.users.push(user); res.status(201).location(`/v1/users/${user.id}`).json(UserSchema.parse(user)); });
  router.get('/v1/users/:userId', (req: Request, res: Response) => { const id = validateRequest(UserIdSchema, req.params.userId, 'Invalid path'); const user = findUser(store, id); if (!user) throw notFound('User not found.'); res.json(UserSchema.parse(user)); });
  router.patch('/v1/users/:userId', idempotency(), (req: Request, res: Response) => { const id = validateRequest(UserIdSchema, req.params.userId, 'Invalid path'); const user = findUser(store, id); if (!user) throw notFound('User not found.'); const body = validateRequest(UpdateUserBodySchema, req.body, 'Invalid body'); if (body.email !== undefined) ensureUniqueEmail(store, body.email, id); const updated = { ...user, ...body, updatedAt: nowIso() }; store.users = store.users.map((u) => (u.id === id ? updated : u)); res.json(UserSchema.parse(updated)); });
  router.delete('/v1/users/:userId', (req: Request, res: Response) => { const id = validateRequest(UserIdSchema, req.params.userId, 'Invalid path'); const before = store.users.length; store.users = store.users.filter((u) => u.id !== id); if (store.users.length === before) throw notFound('User not found.'); res.status(204).end(); });
  return router;
}

export function registerRoutes(app: Router): void { app.use(buildUsersRouter(createStore())); }

