import type { Router, Request, Response } from 'express';
import express from 'express';
import { z } from 'zod';
import { conflict, notFound, unprocessable } from '../lib/problem.ts';
import { paginate, pageSchema, CursorQuerySchema as SharedCursorQuerySchema } from '../lib/pagination.ts';
import { idempotency } from '../lib/idempotency.ts';

const UserIdSchema = z.object({ userId: z.string().uuid() });
const UserRoleSchema = z.enum(['admin', 'member']);
const UserSchema = z.object({
  id: z.string().uuid(),
  email: z.string().email(),
  name: z.string().min(1).max(100),
  role: UserRoleSchema,
  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
});
const UsersListResponseSchema = pageSchema(UserSchema);
const CreateUserBodySchema = z.object({
  email: z.string().email(),
  name: z.string().min(1).max(100),
  role: UserRoleSchema.optional(),
});
const UpdateUserBodySchema = z.object({
  email: z.string().email().optional(),
  name: z.string().min(1).max(100).optional(),
  role: UserRoleSchema.optional(),
}).refine((value) => Object.keys(value).length > 0, { message: 'at least one field is required' });

export type User = z.infer<typeof UserSchema>;
type CreateUserBody = z.infer<typeof CreateUserBodySchema>;
type UpdateUserBody = z.infer<typeof UpdateUserBodySchema>;
type UserIdParams = z.infer<typeof UserIdSchema>;
type Store = z.infer<typeof StoreSchema>;

const StoreSchema = z.object({ users: z.array(UserSchema) });

function nowIso(): string { return new Date().toISOString(); }
function createStore(): Store { return { users: [] }; }
function createUser(input: CreateUserBody): User { const now = nowIso(); return { id: crypto.randomUUID(), email: input.email, name: input.name, role: input.role ?? 'member', createdAt: now, updatedAt: now }; }
function findUser(store: Store, id: string): User | undefined { return store.users.find((u) => u.id === id); }
function ensureUniqueEmail(store: Store, email: string, excludeId?: string): void { if (store.users.some((u) => u.email === email && u.id !== excludeId)) throw conflict('A user with that email already exists.'); }
function validateRequest<T>(schema: z.ZodType<T>, value: unknown, detailPrefix: string): T { const parsed = schema.safeParse(value); if (!parsed.success) throw unprocessable(`${detailPrefix}: ${parsed.error.issues.map((i) => i.path.join('.') || 'body').join(', ')}`); return parsed.data; }

function buildUsersRouter(store: Store): Router {
  const router: Router = express.Router();
  router.get('/v1/users', (req: Request, res: Response) => { const query = SharedCursorQuerySchema.parse(req.query); const page = paginate(store.users, query, (user) => user.id); res.json(UsersListResponseSchema.parse(page)); });
  router.post('/v1/users', idempotency(), (req: Request, res: Response) => { const body = CreateUserBodySchema.parse(req.body); ensureUniqueEmail(store, body.email); const user = createUser(body); store.users.push(user); res.status(201).location(`/v1/users/${user.id}`).json(UserSchema.parse(user)); });
  router.get('/v1/users/:userId', (req: Request, res: Response) => { const { userId } = UserIdSchema.parse(req.params); const user = findUser(store, userId); if (!user) throw notFound('User not found.'); res.json(UserSchema.parse(user)); });
  router.patch('/v1/users/:userId', idempotency(), (req: Request, res: Response) => { const { userId } = UserIdSchema.parse(req.params); const user = findUser(store, userId); if (!user) throw notFound('User not found.'); const body = UpdateUserBodySchema.parse(req.body) as UpdateUserBody; if (body.email !== undefined) ensureUniqueEmail(store, body.email, userId); const updated = { ...user, ...body, updatedAt: nowIso() }; store.users = store.users.map((u) => (u.id === userId ? updated : u)); res.json(UserSchema.parse(updated)); });
  router.delete('/v1/users/:userId', (req: Request, res: Response) => { const { userId } = UserIdSchema.parse(req.params); const before = store.users.length; store.users = store.users.filter((u) => u.id !== userId); if (store.users.length === before) throw notFound('User not found.'); res.status(204).end(); });
  return router;
}

export function registerRoutes(app: Router): void { app.use(buildUsersRouter(createStore())); }

