import request from 'supertest';
import { describe, expect, it } from 'vitest';
import { createApp } from '../src/app.ts';

describe('users api', () => {
  it('supports the users lifecycle and cursor pagination', async () => {
    const app = createApp();

    const created = await request(app)
      .post('/v1/users')
      .send({ email: 'a@example.com', name: 'Alice' })
      .expect(201);

    await request(app)
      .post('/v1/users')
      .send({ email: 'b@example.com', name: 'Bob' })
      .expect(201);

    const firstPage = await request(app).get('/v1/users?limit=1').expect(200);
    expect(firstPage.body.data).toHaveLength(1);
    expect(firstPage.body.nextCursor).toBeTypeOf('string');

    const secondPage = await request(app)
      .get(`/v1/users?limit=1&cursor=${encodeURIComponent(firstPage.body.nextCursor)}`)
      .expect(200);
    expect(secondPage.body.data).toHaveLength(1);
    expect(secondPage.body.nextCursor).toBeNull();

    expect(created.headers.location).toBe(`/v1/users/${created.body.id}`);
    expect(created.body.role).toBe('member');

    await request(app)
      .get(`/v1/users/${created.body.id}`)
      .expect(200)
      .expect(({ body }) => {
        expect(body.email).toBe('a@example.com');
      });

    await request(app)
      .patch(`/v1/users/${created.body.id}`)
      .send({ name: 'Alicia' })
      .expect(200)
      .expect(({ body }) => {
        expect(body.name).toBe('Alicia');
      });

    await request(app).delete(`/v1/users/${created.body.id}`).expect(204);
    await request(app).get(`/v1/users/${created.body.id}`).expect(404);
  });

  it('rejects duplicate emails, invalid input, malformed json, and idempotency misuse', async () => {
    const app = createApp();

    await request(app)
      .post('/v1/users')
      .send({ email: 'dup@example.com', name: 'One' })
      .expect(201);

    await request(app)
      .post('/v1/users')
      .send({ email: 'dup@example.com', name: 'Two' })
      .expect(409)
      .expect('Content-Type', /application\/problem\+json/)
      .expect(({ body }) => {
        expect(body.title).toBe('Conflict');
      });

    await request(app)
      .post('/v1/users')
      .set('Content-Type', 'application/json')
      .send('{')
      .expect(400)
      .expect(({ body }) => {
        expect(body.title).toBe('Bad Request');
      });

    await request(app)
      .post('/v1/users')
      .send({ email: 'bad', name: '' })
      .expect(422)
      .expect(({ body }) => {
        expect(body.detail).toContain('email');
        expect(body.detail).toContain('name');
      });

    await request(app)
      .post('/v1/users')
      .set('Idempotency-Key', 'same-key')
      .send({ email: 'idem@example.com', name: 'Idem' })
      .expect(201);

    await request(app)
      .post('/v1/users')
      .set('Idempotency-Key', 'same-key')
      .send({ email: 'idem@example.com', name: 'Idem' })
      .expect(201)
      .expect('Idempotent-Replayed', 'true');

    await request(app)
      .post('/v1/users')
      .set('Idempotency-Key', 'same-key')
      .send({ email: 'idem-2@example.com', name: 'Other' })
      .expect(422);
  });
});

